[CmdletBinding()]param()
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'ESABCInnovationRun.psm1') -Force;$h=('a'*64);$r=New-ESABCInnovationRun -Requirement 'MOBA镰刀' -GoalRevision 'g1' -SourceHash $h;$ok=$true;$missingOutputRejected=$false
try{Move-ESABCInnovationRun -Run $r -ToStage 'player-outcomes'|Out-Null}catch{if($_.Exception.Message -eq 'INNOVATION_RUN_STAGE_OUTPUT_REQUIRED'){$missingOutputRejected=$true}else{throw}}
try{Move-ESABCInnovationRun -Run $r -ToStage 'tree-expansion'|Out-Null;$ok=$false}catch{if($_.Exception.Message -ne 'INNOVATION_RUN_ILLEGAL_STAGE_TRANSITION'){throw}}
for($i=1;$i -le 3;$i++){Move-ESABCInnovationRun -Run $r -ToStage (@('player-outcomes','lexical-deanchor','seed-divergence')[$i-1]) -Output @{stage='completed'}|Out-Null}
Move-ESABCInnovationRun -Run $r -ToStage 'tree-expansion' -Output @{seedAxes=3}|Out-Null;Add-ESABCInnovationBranch -Run $r -BranchId 'b1' -ParentBranchId '' -Content 'branch-a' -ChangedVariable 'timing' -PlayerAcceptability 80|Out-Null;Add-ESABCInnovationBranch -Run $r -BranchId 'b2' -ParentBranchId 'b1' -Content 'branch-b' -ChangedVariable 'range' -PlayerAcceptability 70|Out-Null;Move-ESABCInnovationRun -Run $r -ToStage 'global-convergence' -Output @{treeBranches=2}|Out-Null;Invoke-ESABCGlobalConvergence -Run $r|Out-Null;Move-ESABCInnovationRun -Run $r -ToStage 'interaction-graph' -Output @{links='verified'}|Out-Null;Move-ESABCInnovationRun -Run $r -ToStage 'adaptive-weighting' -Output @{convergence='verified'}|Out-Null;Update-ESABCInnovationWeights -Run $r -PlayerGap 20 -NoveltyGap 40 -CounterplayGap 10 -ComplexityGap 10|Out-Null;if($r.branchWeights.player -eq $null){$ok=$false};[pscustomobject]@{status=if($ok -and $missingOutputRejected){'passed'}else{'failed'};illegalSkipRejected=$ok;missingOutputRejected=$missingOutputRejected;branchCount=$r.divergenceTree.Count;rejectedCount=@($r.rejectedBranches).Count;weightsPresent=($r.branchWeights.Count -gt 0)}
$seenWeighted=$false;$seedSelectionSeen=$false;$generator={param($ctx) if($ctx.phase -eq 'seed-selection'){$script:seedSelectionSeen=$true;return @([pscustomobject]@{content='axis-a';changedVariable='timing';playerAcceptability=80;novelty=88},[pscustomobject]@{content='axis-b';changedVariable='space';playerAcceptability=82;novelty=86},[pscustomobject]@{content='axis-c';changedVariable='resource';playerAcceptability=78;novelty=90},[pscustomobject]@{content='axis-d';changedVariable='counterplay';playerAcceptability=76;novelty=92},[pscustomobject]@{content='axis-e';changedVariable='cooperation';playerAcceptability=74;novelty=95})};if($ctx.weights.Count -gt 0 -and $ctx.branchBudget -ge 2){$script:seenWeighted=$true};@([pscustomobject]@{content="round-$($ctx.round)-child-a-from-$($ctx.parent.branchId)";changedVariable='timing';playerAcceptability=82;novelty=75},[pscustomobject]@{content="round-$($ctx.round)-child-b-from-$($ctx.parent.branchId)";changedVariable='space';playerAcceptability=70;novelty=80})};$full=Invoke-ESABCInnovationRun -Requirement '完整调度' -GoalRevision 'g2' -SourceHash $h -SeedBranches @('space','timing','counterplay') -SeedConstraints @('保留近战剑盾身份') -ModelInvoker $generator;$requiredCaps=@('bounded-tool-action','failure-recovery','branch-evaluation','state-transition-guard','environment-trust-gate','audit-evidence-chain');$capabilityDispatch=(@($full.capabilityPlan.capabilityRefs).Count -eq 6 -and @($full.capabilityEvidence).Count -ge 3 -and @($full.capabilityEvidence|Where-Object{@($_.executedCapabilities|Sort-Object) -join ',' -ne (@($requiredCaps|Sort-Object)-join ',')}).Count -eq 0);if($full.status -ne 'completed' -or $full.currentStage -ne 'final-decision' -or $full.resourceBudget.modelCallsUsed -lt 12 -or $full.resourceBudget.stageBudgets.'tree-expansion'.modelCalls -lt 16 -or $full.resourceBudget.stageUsage.'tree-expansion'.modelCalls -lt 12 -or @($full.weightHistory).Count -lt 12 -or -not $script:seenWeighted -or -not $script:seedSelectionSeen -or $full.stageOutputs['seed-divergence'].selectionAuthority -ne 'ABCD' -or -not $capabilityDispatch){throw 'FULL_INNOVATION_RUN_NOT_COMPLETED'};[pscustomobject]@{status='passed';stageBudgeted=$true;weightsApplied=$true;capabilityDispatch=$true;capabilityEvidenceEntries=@($full.capabilityEvidence).Count;selectedSeedCount=$full.stageOutputs['seed-divergence'].selectedCount;weightRounds=@($full.weightHistory).Count;treeExpansionCalls=$full.resourceBudget.stageUsage.'tree-expansion'.modelCalls;modelCallsUsed=$full.resourceBudget.modelCallsUsed}
